// [MEDIUM_PRIORITY] PERFORMANCE: String Concatenation optimized
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.engineimport com.roshan.persona.cognitive.model.CognitiveConfig/** * NOUS — Confidence Modulator (Module 7 v2 — Step 7.2, P0). * * Maps reasoning confidence to response tone. NOUS sounds different when * it's 95% sure vs 60% sure — this prevents overconfident wrong answers. * * ## Confidence → Tone mapping (per strategy v2 §"ConfidenceModulator") * * | Confidence | Tone | Example | * |-----------|------|---------| * | ≥ 0.9 | **Assertive** | "I recommend the train." | * | 0.7 – 0.9 | **Cautious** | "I suggest the train, but you should verify the schedule." | * | < 0.7 | **Defer** | "I'm not fully confident, but the train might work. Could you double-check?" | * * ## Integration * * Called by [com.roshan.persona.cognitive.engine.CognitiveFacade] AFTER * reasoning + AFTER [UncertaintyAwareness] (which may intercept if * confidence is too low). If UncertaintyAwareness returns [UncertaintyAction.Answer], * ConfidenceModulator wraps the answer with the appropriate tone. * * ## Why this matters * * Top assistants (ChatGPT, Claude) modulate their certainty — they say * "I believe" or "you should verify" when they're not 100% sure. This * builds user trust. NOUS does the same, but the tone is also persona-driven: *  - Atlas says "I would suggest, sir, that you verify..." *  - Onyx says "Uncertain. Verify." *  - Aria says "I'm pretty sure, but maybe double-check?" * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§ConfidenceModulator</a> */class ConfidenceModulator(    private val config: CognitiveConfig = CognitiveConfig(),) {    /**     * Modulate response tone based on [confidence].     *     * Wraps [recommendation] with a confidence-appropriate prefix/suffix.     *     * Uses 5 tones per strategy §8:     *  - **CONFIDENT** (≥0.9) — assertive, no hedging     *  - **ENTHUSIASTIC** (0.85–0.9, Aria/Nova only) — exclamation, energy     *  - **TENTATIVE** (0.7–0.85) — "I believe", suggests verification     *  - **CAUTIOUS** (0.5–0.7) — "maybe", explicit uncertainty     *  - **CASUAL** (Echo persona only, ≥0.7) — "yeah", colloquial     *     * @param confidence the reasoning confidence (0.0–1.0).     * @param recommendation the raw recommendation text ("Take the train to Goa").     * @param personaId the active persona ID (for persona-styled modulation).     * @return the modulated recommendation.     */    fun modulate(confidence: Float, recommendation: String, personaId: String = "default"): String {        require(confidence in 0f..1f) { "confidence must be in [0,1], got $confidence" }        require(recommendation.isNotBlank()) { "recommendation must not be blank" }        val tone = classifyTone(confidence, personaId)        return when (tone) {            Tone.CONFIDENT -> formatConfident(recommendation, personaId)            Tone.ENTHUSIASTIC -> formatEnthusiastic(recommendation, personaId)            Tone.TENTATIVE -> formatTentative(recommendation, personaId)            Tone.CAUTIOUS -> formatCautious(recommendation, personaId)            Tone.CASUAL -> formatCasual(recommendation, personaId)        }    }    /**     * Get the [Tone] for [confidence] + persona without formatting.     */    fun getTone(confidence: Float, personaId: String = "default"): Tone {        require(confidence in 0f..1f) { "confidence must be in [0,1]" }        return classifyTone(confidence, personaId)    }    private fun classifyTone(confidence: Float, personaId: String): Tone {        // Persona-driven: Echo is always CASUAL for medium+ confidence.        if (personaId == "echo" && confidence >= config.confidenceCautiousThreshold) {            return Tone.CASUAL        }        // Persona-driven: Aria/Nova are ENTHUSIASTIC for high (but not max) confidence.        if (personaId in setOf("aria", "nova") &&            confidence in 0.85f..config.confidenceAssertiveThreshold) {            return Tone.ENTHUSIASTIC        }        return when {            confidence >= config.confidenceAssertiveThreshold -> Tone.CONFIDENT            confidence >= config.confidenceCautiousThreshold -> Tone.TENTATIVE            else -> Tone.CAUTIOUS        }    }    // ─── Tone formatters (5 tones) ─────────────────────────────────────────    private fun formatConfident(recommendation: String, personaId: String): String = when (personaId) {        "atlas" -> "I recommend $recommendation"        "nova" -> "$recommendation! That's my pick."        "onyx" -> recommendation.replaceFirstChar { it.uppercase() }  // terse, no hedging        "sage" -> "I'm confident — $recommendation".replaceFirstChar { it.lowercase() }        "echo" -> "$recommendation — yeah, go for it."        "vanguard" -> "Confirmed: $recommendation".replaceFirstChar { it.lowercase() }        "aria" -> "$recommendation! I'm sure of it!"        "wraith" -> recommendation.replaceFirstChar { it.uppercase() }        "zenith" -> "$recommendation".replaceFirstChar { it.uppercase() }        else -> "I recommend $recommendation"    }    private fun formatEnthusiastic(recommendation: String, personaId: String): String = when (personaId) {        "aria" -> "$recommendation! I'm super excited about this one!"        "nova" -> "$recommendation! Oh, this is going to be great!"        else -> "$recommendation! I'm excited about this!"    }    private fun formatTentative(recommendation: String, personaId: String): String = when (personaId) {        "atlas" -> "I would suggest $recommendation, though you may wish to verify the details."        "nova" -> "I think $recommendation, but maybe double-check?"        "onyx" -> "Probable: $recommendation".replaceFirstChar { it.lowercase() } + ". Verify."        "sage" -> "I believe $recommendation might work, but please verify."        "echo" -> "$recommendation — probably, but I'd check first."        "vanguard" -> "Likely: $recommendation".replaceFirstChar { it.lowercase() } + ". Verify."        "aria" -> "I'm pretty sure $recommendation, but maybe double-check?"        "wraith" -> "Maybe: $recommendation".replaceFirstChar { it.lowercase() } + "."        "zenith" -> "$recommendation".replaceFirstChar { it.uppercase() } + " — please verify."        else -> "I suggest $recommendation, but you should verify the details."    }    private fun formatCautious(recommendation: String, personaId: String): String = when (personaId) {        "atlas" -> "I'm not entirely certain, sir, but $recommendation might be worth considering."        "nova" -> "Hmm, I'm not sure, but $recommendation could work? What do you think?"        "onyx" -> "Uncertain. $recommendation".replaceFirstChar { it.uppercase() } + " — unverified."        "sage" -> "I'm not fully confident, but $recommendation might be a starting point."        "echo" -> "$recommendation — maybe? I'm not super sure about this one."        "vanguard" -> "Low confidence: $recommendation".replaceFirstChar { it.lowercase() } + ". Requires verification."        "aria" -> "I'm not sure, but $recommendation might work? Could you check?"        "wraith" -> "Unsure. $recommendation".replaceFirstChar { it.uppercase() } + "."        "zenith" -> "$recommendation".replaceFirstChar { it.uppercase() } + " — low confidence. Please verify."        else -> "I'm not fully confident, but $recommendation might work. Could you double-check?"    }    private fun formatCasual(recommendation: String, personaId: String): String = when (personaId) {        "echo" -> "$recommendation — yeah, sounds good, mate."        else -> "$recommendation — sounds good."    }}// ──────────────────────────────────────────────────────────────────────────/** * Response tone based on confidence level + persona. * * Strategy §8 specifies 5 tones mapped to specific personas: *  - **CONFIDENT** → Atlas, Vanguard, Onyx, Sage (high confidence) *  - **ENTHUSIASTIC** → Aria, Nova (high but not max confidence) *  - **TENTATIVE** → Sage (medium confidence) *  - **CAUTIOUS** → Wraith (low-medium confidence) *  - **CASUAL** → Echo (medium+ confidence) * * Audit Task ID: audit-m8-cognitive P1 — was 3 tones (ASSERTIVE/CAUTIOUS/DEFER), * now 5 (CONFIDENT/ENTHUSIASTIC/TENTATIVE/CAUTIOUS/CASUAL). */enum class Tone(val displayLabel: String) {    /** Confidence ≥ 0.9 — assertive, no hedging. (Atlas, Vanguard, Onyx) */    CONFIDENT("Confident"),    /** High confidence + energetic persona (Aria, Nova) — exclamation, energy. */    ENTHUSIASTIC("Enthusiastic"),    /** Medium-high confidence — "I believe", suggests verification. (Sage) */    TENTATIVE("Tentative"),    /** Low-medium confidence — "maybe", explicit uncertainty. (Wraith) */    CAUTIOUS("Cautious"),    /** Medium+ confidence + casual persona (Echo) — colloquial, relaxed. */    CASUAL("Casual"),}